+/* ── Reset & base ─────────────────────────────────────────── */
+*, *::before, *::after {
+  box-sizing: border-box;
+  margin: 0;
+  padding: 0;
+}
+
+:root {
+  --color-bg:           #0f1117;
+  --color-surface:      #1a1d27;
+  --color-surface-alt:  #222636;
+  --color-border:       #2e3347;
+  --color-border-focus: #6c8cff;
+  --color-border-error: #f06a6a;
+  --color-text:         #e4e6f0;
+  --color-text-muted:   #8a90a8;
+  --color-accent:       #6c8cff;
+  --color-accent-hover: #8aa3ff;
+  --color-accent-active:#5070e0;
+  --color-error:        #f06a6a;
+  --color-error-bg:     rgba(240, 106, 106, 0.08);
+  --color-success:      #56d07e;
+  --color-required:     #f06a6a;
+
+  --radius:   8px;
+  --radius-sm: 4px;
+  --shadow:   0 4px 24px rgba(0, 0, 0, 0.45);
+  --transition: 150ms ease;
+}
+
+html {
+  font-size: 16px;
+  scroll-behavior: smooth;
+}
+
+body {
+  background-color: var(--color-bg);
+  color: var(--color-text);
+  font-family: system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
+  line-height: 1.6;
+  min-height: 100dvh;
+  display: flex;
+  flex-direction: column;
+}
+
+/* ── Skip link ────────────────────────────────────────────── */
+.skip-link {
+  position: absolute;
+  top: -3rem;
+  left: 1rem;
+  background: var(--color-accent);
+  color: #fff;
+  padding: 0.5rem 1rem;
+  border-radius: var(--radius-sm);
+  font-weight: 600;
+  text-decoration: none;
+  z-index: 100;
+  outline: 2px solid transparent;
+  outline-offset: 2px;
+  transition: top var(--transition);
+}
+
+.skip-link:focus {
+  top: 1rem;
+  outline-color: var(--color-border-focus);
+}
+
+/* ── Header ───────────────────────────────────────────────── */
+header {
+  background: var(--color-surface);
+  border-bottom: 1px solid var(--color-border);
+  padding: 0.875rem 1.5rem;
+}
+
+.header-inner {
+  max-width: 640px;
+  margin: 0 auto;
+  display: flex;
+  align-items: center;
+  gap: 0.625rem;
+}
+
+.logo {
+  font-size: 1.5rem;
+  color: var(--color-accent);
+  line-height: 1;
+}
+
+.site-name {
+  font-size: 1.0625rem;
+  font-weight: 600;
+  letter-spacing: 0.01em;
+  color: var(--color-text);
+}
+
+/* ── Main ─────────────────────────────────────────────────── */
+main {
+  flex: 1;
+  display: flex;
+  align-items: flex-start;
+  justify-content: center;
+  padding: 3rem 1rem 4rem;
+}
+
+/* ── Form section ─────────────────────────────────────────── */
+.form-section {
+  width: 100%;
+  max-width: 480px;
+  background: var(--color-surface);
+  border: 1px solid var(--color-border);
+  border-radius: calc(var(--radius) * 1.5);
+  padding: 2.25rem 2.5rem 2.5rem;
+  box-shadow: var(--shadow);
+}
+
+h1 {
+  font-size: 1.625rem;
+  font-weight: 700;
+  letter-spacing: -0.01em;
+  color: var(--color-text);
+  margin-bottom: 0.375rem;
+}
+
+.form-intro {
+  color: var(--color-text-muted);
+  font-size: 0.9375rem;
+  margin-bottom: 1.75rem;
+}
+
+/* ── Status banner ────────────────────────────────────────── */
+.form-status {
+  border-radius: var(--radius-sm);
+  font-size: 0.9375rem;
+  font-weight: 500;
+  /* Hidden until populated */
+}
+
+.form-status:not(:empty) {
+  padding: 0.75rem 1rem;
+  margin-bottom: 1.5rem;
+}
+
+.form-status.success {
+  background: rgba(86, 208, 126, 0.1);
+  color: var(--color-success);
+  border: 1px solid rgba(86, 208, 126, 0.3);
+}
+
+.form-status.error {
+  background: var(--color-error-bg);
+  color: var(--color-error);
+  border: 1px solid rgba(240, 106, 106, 0.3);
+}
+
+/* ── Form fields ──────────────────────────────────────────── */
+.form-field {
+  display: flex;
+  flex-direction: column;
+  gap: 0.375rem;
+  margin-bottom: 1.25rem;
+}
+
+label {
+  font-size: 0.875rem;
+  font-weight: 600;
+  color: var(--color-text);
+  letter-spacing: 0.015em;
+}
+
+.required-indicator {
+  color: var(--color-required);
+  margin-left: 2px;
+}
+
+input[type="text"],
+input[type="email"],
+input[type="tel"] {
+  background: var(--color-surface-alt);
+  color: var(--color-text);
+  border: 1.5px solid var(--color-border);
+  border-radius: var(--radius-sm);
+  padding: 0.625rem 0.875rem;
+  font-size: 1rem;
+  font-family: inherit;
+  line-height: 1.5;
+  width: 100%;
+  transition: border-color var(--transition), box-shadow var(--transition);
+  outline: 2px solid transparent;
+  outline-offset: 2px;
+  /* Prevent iOS zoom on focus */
+  min-height: 2.75rem;
+}
+
+input::placeholder {
+  color: var(--color-text-muted);
+  opacity: 0.7;
+}
+
+input:hover {
+  border-color: #3e4460;
+}
+
+input:focus {
+  border-color: var(--color-border-focus);
+  box-shadow: 0 0 0 3px rgba(108, 140, 255, 0.2);
+  outline: 2px solid transparent;
+}
+
+/* Visible focus fallback for forced-colors */
+@media (forced-colors: active) {
+  input:focus {
+    outline: 2px solid ButtonText;
+  }
+}
+
+input[aria-invalid="true"] {
+  border-color: var(--color-border-error);
+  background: var(--color-error-bg);
+}
+
+input[aria-invalid="true"]:focus {
+  box-shadow: 0 0 0 3px rgba(240, 106, 106, 0.2);
+}
+
+/* ── Helper & error text ──────────────────────────────────── */
+.field-hint {
+  font-size: 0.8125rem;
+  color: var(--color-text-muted);
+  line-height: 1.4;
+}
+
+.field-error {
+  font-size: 0.8125rem;
+  color: var(--color-error);
+  line-height: 1.4;
+  min-height: 0;   /* collapses when empty */
+}
+
+.field-error:empty {
+  display: none;
+}
+
+/* ── Required note ────────────────────────────────────────── */
+.required-note {
+  font-size: 0.8125rem;
+  color: var(--color-text-muted);
+  margin-bottom: 1.5rem;
+}
+
+.required-note span {
+  color: var(--color-required);
+}
+
+/* ── Submit button ────────────────────────────────────────── */
+.submit-btn {
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  width: 100%;
+  padding: 0.75rem 1.5rem;
+  background: var(--color-accent);
+  color: #fff;
+  font-size: 1rem;
+  font-family: inherit;
+  font-weight: 600;
+  border: none;
+  border-radius: var(--radius-sm);
+  cursor: pointer;
+  transition: background var(--transition), transform 80ms ease;
+  outline: 2px solid transparent;
+  outline-offset: 2px;
+  min-height: 2.75rem;
+}
+
+.submit-btn:hover {
+  background: var(--color-accent-hover);
+}
+
+.submit-btn:active {
+  background: var(--color-accent-active);
+  transform: translateY(1px);
+}
+
+.submit-btn:focus-visible {
+  outline: 2px solid var(--color-border-focus);
+  outline-offset: 3px;
+  box-shadow: 0 0 0 4px rgba(108, 140, 255, 0.25);
+}
+
+@media (forced-colors: active) {
+  .submit-btn {
+    border: 2px solid ButtonText;
+    forced-color-adjust: none;
+    background: ButtonFace;
+    color: ButtonText;
