+  // Validation rules per field
+  const fields = [
+    {
+      input: document.getElementById('full-name'),
+      errorEl: document.getElementById('full-name-error'),
+      validate(value) {
+        if (!value.trim()) return 'Full name is required.';
+        if (value.trim().length < 2) return 'Please enter at least 2 characters.';
+        return null;
+      },
+    },
+    {
+      input: document.getElementById('email'),
+      errorEl: document.getElementById('email-error'),
+      validate(value) {
+        if (!value.trim()) return 'Email address is required.';
+        // RFC-5321 rough check — good enough for client-side UX
+        if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim())) {
+          return 'Please enter a valid email address (e.g. you@example.com).';
+        }
+        return null;
+      },
+    },
+    {
+      input: document.getElementById('phone'),
+      errorEl: document.getElementById('phone-error'),
+      validate(value) {
+        if (!value.trim()) return null; // optional
+        // Allow digits, spaces, dashes, dots, parentheses, leading +
+        if (!/^\+?[\d\s\-().]{7,20}$/.test(value.trim())) {
+          return 'Please enter a valid phone number (e.g. +1 (555) 000-0000).';
+        }
+        return null;
+      },
+    },
+  ];
+
+  function showError(field, message) {
+    field.errorEl.textContent = message;
+    field.input.setAttribute('aria-invalid', 'true');
+  }
+
+  function clearError(field) {
+    field.errorEl.textContent = '';
+    field.input.removeAttribute('aria-invalid');
+  }
+
+  function validateField(field) {
+    const error = field.validate(field.input.value);
+    if (error) {
+      showError(field, error);
+      return false;
+    }
+    clearError(field);
+    return true;
+  }
+
+  // Validate on blur — but only after the field has been interacted with
+  fields.forEach((field) => {
+    field.input.addEventListener('blur', () => {
+      validateField(field);
+    });
